import sys

input = sys.stdin.read().strip()

def find_expression(s):
    n = len(s)
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            a = s[:i]
            b = s[i:j]
            c = s[j:]
            if a[0] != '0' and b[0] != '0' and c[0] != '0':
                if int(a) + int(b) == int(c):
                    return f"{a}+{b}={c}"

print(find_expression(input))
